import { DIFFICULTIES, boardGoal } from './management.js';
import { TACTICAL_STYLES, styleName } from './styles.js';
import { assistantAdvice, proactiveAdvice, recommendationPlan, applyRecommendation } from './assistant.js';
import * as E from './engine.js';
import {loadBundledDatabase,ATTRIBUTES,LABELS} from './database.js';
import {initEditor,renderEditor,bindEditor,getEditorDatabase,leagueFields,readLeagueForm} from './editor.js';
import {esc,money,compactMoney,title,crest,option,options,field,numberInput,icon,toast,showModal,confirmAction,download,pickFile,errorsHTML} from './ui.js';
import {formationPoints,startPitch} from './pitch.js';
const SAVE_KEY='touchline-career-v1';
const app=document.querySelector('#app');let db,state=null,view='dashboard',leagueTab='table',leagueRound=0,chosenLeague='',customDB=false,careerDifficulty='Medium',careerSeed=2026,transferFilter='',transferPos='',transferClub='',squadSort='position',timer=null,pitchStop=null,playing=false,speed=2,saveTime=null,saveFailed=false;
const myClub=()=>E.club(state,state.userClubId);
const badge=n=>`<span class="number-badge ${n<60?'warn':''}">${Math.round(n)}</span>`;
const rating=p=>Math.round(E.ability(p));
const fit=p=>`<span class="fit"><span class="meter"><i style="width:${p.fitness}%;background:${p.fitness<65?'var(--gold)':'var(--accent)'}"></i></span>${Math.round(p.fitness)}%</span>`;
const formPills=form=>`<div class="form">${form.slice(-5).map(v=>`<span class="${v}">${v}</span>`).join('')}</div>`;
function save(){if(!state)return;try{localStorage.setItem(SAVE_KEY,E.serialize(state));saveTime=new Date();saveFailed=false;}catch{saveFailed=true;toast('Autosave failed: browser storage may be full or disabled. Export your career to keep it.',true);}updateSaveLabel();}
function updateSaveLabel(){document.querySelectorAll('.save-info').forEach(el=>el.innerHTML=`<span class="save-dot" style="background:${saveFailed?'var(--red)':'var(--accent)'}"></span>${saveFailed?'Save failed · export now':saveTime?'Saved locally':'Local autosave'}`);}
function pause(){playing=false;clearInterval(timer);timer=null;}
function navigate(next){pause();view=next;save();render();window.scrollTo({top:0});}
function runAction(fn,redraw=true){try{fn();save();if(redraw)render();}catch(e){toast(e.message,true);}}
function render(){pitchStop?.();pitchStop=null;
  if(!state&&view!=='editor'){renderSelection();return;}
  const c=state?myClub():null,f=state?E.nextFixture(state):null,complete=state&&state.round===state.fixtures.length;
  const navs=[['dashboard','Overview'],['squad','Squad'],['tactics','Tactics'],['transfers','Transfers'],['training','Training'],['league','League'],['finances','Club & finances'],['editor','Database studio']];
  app.innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" aria-label="Touchline Twelve home" href="#" data-go="${state?'dashboard':'selection'}"><img src="./assets/crest.svg" alt=""><div>TOUCHLINE<br><span>TWELVE</span></div></a>${c?`<div class="club-mini">${crest(c)}<div><strong>${esc(c.name)}</strong><p>FIRST TEAM MANAGER</p></div></div>`:''}<nav class="nav" aria-label="Main navigation">${navs.filter(([id])=>state||id==='editor').map(([id,name])=>`<button data-go="${id}" aria-label="${esc(name)}" title="${esc(name)}" class="${view===id?'active':''}">${icon(id)}<span>${name}</span></button>`).join('')}${state?.activeMatch?`<button data-go="match" aria-label="Match centre" class="${view==='match'?'active':''}">${icon('play')}<span>Match centre · ${state.activeMatch.minute}′</span></button>`:''}</nav><div class="sidebar-bottom">${state?`<button class="btn ghost" aria-label="Export career" data-action="export-save">${icon('save')}<span>Export career</span></button>`:''}<button class="btn ghost" aria-label="Import career" data-action="import-save">${icon('import')}<span>Import career</span></button><button class="btn ghost" aria-label="New career" data-action="new-career">${icon('home')}<span>${state?'New career…':'Choose a club'}</span></button><button class="btn ghost" aria-label="How to play" data-action="help">${icon('help')}<span>How to play</span></button><div class="small muted save-info"><span class="save-dot"></span>Local autosave</div><div class="tiny muted save-info-secondary">v1.0 · Your game, your pace</div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb"><span>${state?esc(state.league.name):'DATABASE STUDIO'}</span>${icon('chevron')}<b>${esc(navs.find(([id])=>id===view)?.[1]||'Match centre')}</b></div><div class="top-actions">${state?`<button class="btn ghost assistant-ask" data-action="ask-assistant">${icon('squad')}<span>Ask Assistant</span></button><span class="season-text tiny muted">${state.difficulty.toUpperCase()} · SEASON ${state.season} · WEEK ${Math.min(state.round+1,state.fixtures.length)} / ${state.fixtures.length}</span>${view!=='match'?`<button class="btn primary" data-action="continue">${state.activeMatch?'Resume match':complete?'Next season':f?'Play match':'Advance bye'} ${icon('arrow')}</button>`:''}`:'<button class="btn primary" data-action="new-career">Choose a club →</button>'}</div></header><main class="content">${view==='editor'?renderEditor(!!state):view==='dashboard'?dashboard():view==='squad'?squadView():view==='tactics'?tacticsView():view==='transfers'?transfersView():view==='training'?trainingView():view==='league'?leagueView():view==='finances'?financeView():matchView()}<footer class="page-footer"><span>TOUCHLINE TWELVE <span class="muted">/</span> Football, on your terms.</span><span>${state?`Seed ${state.seed} · ${state.difficulty} · ${esc(state.league.name)}`:'Editable data · Static web · No account required'}</span></footer></main></div></div>`;
  bindCommon();if(view==='editor')bindEditor(app);else if(view==='squad')bindSquad();else if(view==='tactics')bindTactics();else if(view==='transfers')bindTransfers();else if(view==='training')bindTraining();else if(view==='league')bindLeague();else if(view==='finances')bindFinance();else if(view==='match'){bindMatch();const canvas=document.querySelector('#match-pitch');pitchStop=startPitch(canvas,()=>state.activeMatch,()=>state,()=>playing);if(playing)startClock();}
  updateSaveLabel();
}
function heading(name,description,extra=''){return `<div class="page-heading"><div><h1>${name}</h1><p>${description}</p></div>${extra}</div>`;}
function table(rows,full=true){return `<div class="table-wrap"><table><thead><tr><th class="center">#</th><th>Club</th><th class="center">P</th>${full?'<th class="center">W</th><th class="center">D</th><th class="center">L</th><th class="center">GF</th><th class="center">GA</th>':''}<th class="center">GD</th><th class="center">Pts</th><th>Form</th></tr></thead><tbody>${rows.map((c,i)=>`<tr class="${c.id===state.userClubId?'user-row':''}"><td class="center rank">${i+1}</td><td><div class="team-name">${crest(c,'sm')}${esc(c.name)}${c.id===state.userClubId?'<span class="tag green">YOU</span>':''}</div></td><td class="center muted">${c.played}</td>${full?`<td class="center">${c.w}</td><td class="center">${c.d}</td><td class="center">${c.l}</td><td class="center muted">${c.gf}</td><td class="center muted">${c.ga}</td>`:''}<td class="center">${c.gf-c.ga>0?'+':''}${c.gf-c.ga}</td><td class="center"><strong>${c.points}</strong></td><td>${formPills(c.form)}</td></tr>`).join('')}</tbody></table></div>`;}
function dashboard(){const c=myClub(),f=E.nextFixture(state),rows=E.standings(state),rank=rows.findIndex(t=>t.id===c.id)+1;const own=rows[rank-1],roster=E.squad(state,c.id),wages=roster.reduce((n,p)=>n+p.wage,0),finished=state.round===state.fixtures.length;
  const opponent=f?E.club(state,f.home===c.id?f.away:f.home):null;
  return `${heading('Welcome to the dugout.',`${esc(c.name)} · ${esc(c.stadium)} · Season ${state.season}`,`<span class="tag green">${state.activeMatch?'MATCH IN PROGRESS':finished?'SEASON COMPLETE':'MANAGER’S OFFICE'}</span>`)}<section class="hero"><div><div class="eyebrow">${finished?'The final whistle':'Your next chapter'}</div><h2>${finished?'A season to remember.':state.activeMatch?'The game is waiting.':f?'One match. Everything to play for.':'A week to regroup.'}</h2><p>${finished?`${esc(rows[0].name)} are champions. You finished ${rank} of ${rows.length}. Prize money has arrived.`:f?`Prepare your squad, find your edge, and take ${esc(c.name)} into matchweek ${state.round+1}.`:'Your club has a bye this week. The league still plays, while your players train and recover.'}</p><div class="actions"><button class="btn primary" data-action="continue">${finished?'Begin next season':state.activeMatch?'Return to match':f?'Go to match':'Advance week'} ${icon('arrow')}</button><button class="btn ghost" data-go="squad">Review squad</button></div></div><div class="fixture-hero"><div class="eyebrow">${f?`${f.home===c.id?'Home':'Away'} fixture · Matchweek ${state.round+1}`:finished?'League champions':'This week'}</div><div class="fixture-teams">${f?`<div class="fixture-team">${crest(E.club(state,f.home),'large')}<span>${esc(E.club(state,f.home).name)}</span></div><span class="fixture-vs">vs</span><div class="fixture-team">${crest(E.club(state,f.away),'large')}<span>${esc(E.club(state,f.away).name)}</span></div>`:`<div class="fixture-team">${crest(finished?rows[0]:c,'large')}<span>${esc(finished?rows[0].name:c.name)}</span></div>`}</div><p class="small" style="text-align:center">${f?esc(E.club(state,f.home).stadium):finished?`${rows[0].points} points · ${rows[0].gf} goals`:'Recovery and training week'}</p></div></section><div class="stats"><div class="stat"><div class="label">League position ${icon('league')}</div><div class="value">${rank}<span class="muted" style="font-size:14px;font-weight:400"> / ${rows.length}</span></div><div class="foot">${own.points} points · ${own.played} matches played</div></div><div class="stat"><div class="label">Club balance ${icon('finances')}</div><div class="value ${c.balance<0?'negative':''}">${compactMoney(c.balance)}</div><div class="foot">${compactMoney(wages)} weekly wage bill</div></div><div class="stat"><div class="label">Squad readiness ${icon('squad')}</div><div class="value">${Math.round(roster.reduce((a,p)=>a+p.fitness,0)/roster.length)}<span style="font-size:15px">%</span></div><div class="foot">${roster.filter(p=>p.injury).length} injured · ${roster.length} players</div></div><div class="stat"><div class="label">Board confidence ${icon('training')}</div><div class="value positive">${state.boardConfidence}<span style="font-size:15px">%</span></div><div class="foot">Expectation: ${esc(boardGoal(state,c))}</div></div></div>${assistantPanel()}<div class="grid two"><section class="panel"><div class="panel-head"><h2>The title race</h2><button class="text-btn small positive" data-go="league">Full table →</button></div>${table(rows.slice(0,6),false)}${rank>6?`<div class="panel-body small muted">Your club: ${rank} · ${own.points} points · ${own.gf-own.ga} goal difference</div>`:''}</section><section class="panel"><div class="panel-head"><h2>From around the club</h2><span class="tag">NEWS</span></div>${state.news.slice(0,4).map(n=>`<div class="news-item"><div class="news-icon">${icon('news')}</div><div><div class="stamp">Season ${n.season} · Week ${n.round+1}</div><p>${esc(n.text)}</p></div></div>`).join('')}</section></div><section class="panel" style="margin-top:20px"><div class="panel-head"><h2>On the horizon</h2><span class="small muted">Your next fixtures</span></div>${state.fixtures.slice(state.round,state.round+4).map((rr,i)=>{const ff=rr.find(f=>f.home===c.id||f.away===c.id);return ff?`<div class="fixture-row"><span class="tag">MW ${state.round+i+1}</span>${crest(E.club(state,ff.home===c.id?ff.away:ff.home),'sm')}<strong class="grow">${esc(E.club(state,ff.home===c.id?ff.away:ff.home).name)}</strong><span class="muted">${esc(E.club(state,ff.home).stadium)}</span><span class="tag ${ff.home===c.id?'green':''}">${ff.home===c.id?'HOME':'AWAY'}</span></div>`:`<div class="fixture-row"><span class="tag">MW ${state.round+i+1}</span><span class="muted">Bye · recovery week</span></div>`;}).join('')||'<div class="empty">All fixtures complete. Begin a new season when you’re ready.</div>'}</section>`;
}
function rosterOptions(ids,selected,slot=null){return ids.map(id=>{const p=E.player(state,id);return option(id,`${p.name} · ${p.primaryPosition} · ${rating(p)}${p.injury?' · INJURED':''}${slot&&p.position!==slot?' · out of position':''}`,selected);}).join('');}
function lineupControls(c){const roster=E.squad(state,c.id).filter(p=>!p.injury).map(p=>p.id),slots=E.FORMATIONS[c.tactics.formation];return `<div class="panel"><div class="panel-head"><h2>Starting XI</h2><button class="btn sm" data-action="auto-lineup">Auto pick</button></div><div class="panel-body">${slots.map((pos,i)=>`<label class="lineup-item"><span class="lineup-pos">${pos}</span><select aria-label="Starter ${i+1} ${pos}" data-lineup="${i}" ${state.activeMatch?'disabled':''}>${option('','Select player',c.lineup[i])}${rosterOptions(pos==='GK'?roster.filter(id=>E.player(state,id).position==='GK'):roster,c.lineup[i],pos)}</select><span class="tiny muted">${i+1}</span></label>`).join('')}<h3 style="margin:20px 0 10px">Bench <span class="muted small">/ up to 7</span></h3>${Array.from({length:7},(_,i)=>`<label class="lineup-item"><span class="lineup-pos">S${i+1}</span><select aria-label="Bench ${i+1}" data-bench="${i}" ${state.activeMatch?'disabled':''}>${option('','Empty',c.bench[i]||'')}${rosterOptions(roster.filter(id=>!c.lineup.includes(id)),c.bench[i])}</select><span></span></label>`).join('')}<div class="field-grid" style="margin-top:20px">${field('Captain',`<select data-captain ${state.activeMatch?'disabled':''}>${rosterOptions(c.lineup.filter(Boolean),c.captain)}</select>`)}${field('Set-piece taker',`<select data-setpiece ${state.activeMatch?'disabled':''}>${rosterOptions(c.lineup.filter(Boolean),c.setPiece)}</select>`)}</div><p class="help">Selecting a starter swaps players already in the XI. Out-of-position players are less effective. Bench selections must be unique; five substitutions per match.</p></div></div>`;}
function squadView(){const c=myClub(),roster=E.squad(state,c.id).sort((a,b)=>squadSort==='rating'?rating(b)-rating(a):squadSort==='age'?a.age-b.age:squadSort==='fitness'?b.fitness-a.fitness:['GK','DEF','MID','FWD'].indexOf(a.position)-['GK','DEF','MID','FWD'].indexOf(b.position)||rating(b)-rating(a));const error=E.validateLineup(state,c);return `${heading('The squad.',`${roster.length} players · Select your eleven, choose your leaders.`, `<select id="squad-sort" aria-label="Sort squad">${[['position','Position'],['rating','Ability'],['age','Age'],['fitness','Fitness']].map(([v,t])=>option(v,t,squadSort)).join('')}</select>`)}${error?`<div class="notice warn">${esc(error)}</div>`:''}${state.activeMatch?'<div class="notice">A match is in progress. Make substitutions in the match centre; pre-match selection is locked.</div>':''}<div class="grid squad-layout"><div class="panel"><div class="table-wrap"><table><thead><tr><th>Player</th><th>Pos</th><th>Age</th><th>Ability</th><th>Pot</th><th>Fitness</th><th>Morale</th><th>Apps</th><th>G / A</th></tr></thead><tbody>${roster.map(p=>`<tr><td><button class="text-btn" data-player="${esc(p.id)}">${esc(p.name)}</button><div class="tiny muted">${p.injury?`<span class="negative">Injured · ${p.injury} weeks</span>`:c.lineup.includes(p.id)?'<span class="positive">STARTER</span>':c.bench.includes(p.id)?'BENCH':'RESERVE'}${c.captain===p.id?' · CAPTAIN':''}</div></td><td><span class="tag">${p.primaryPosition}</span></td><td>${p.age}</td><td>${badge(rating(p))}</td><td class="gold">${p.potential}</td><td>${fit(p)}</td><td class="${p.morale<50?'negative':'muted'}">${Math.round(p.morale)}</td><td>${p.appearances}</td><td>${p.goals} / ${p.assists}</td></tr>`).join('')}</tbody></table></div><div class="panel-body help">Click a player to see attributes, wages, and contract details. Attributes, fitness, morale, roles, and position fit all affect matches.</div></div>${lineupControls(c)}</div>`;}
function bindSquad(){document.querySelector('#squad-sort').onchange=e=>{squadSort=e.target.value;render();};app.querySelectorAll('[data-lineup]').forEach(el=>el.onchange=()=>runAction(()=>{if(state.activeMatch)throw Error('Use match substitutions.');const c=myClub(),i=Number(el.dataset.lineup),id=el.value;if(!id)return;const old=c.lineup[i],other=c.lineup.indexOf(id);if(other>=0)c.lineup[other]=old;c.lineup[i]=id;c.bench=c.bench.filter(x=>!c.lineup.includes(x));ensureLeaders(c);}));app.querySelectorAll('[data-bench]').forEach(el=>el.onchange=()=>runAction(()=>{const c=myClub(),i=Number(el.dataset.bench),id=el.value;const values=Array.from(app.querySelectorAll('[data-bench]'),x=>x===el?id:x.value).filter(Boolean);if(new Set(values).size!==values.length){render();throw Error('Bench players must be unique.');}c.bench=values;}));app.querySelector('[data-captain]').onchange=e=>runAction(()=>myClub().captain=e.target.value,false);app.querySelector('[data-setpiece]').onchange=e=>runAction(()=>myClub().setPiece=e.target.value,false);}
function ensureLeaders(c){if(!c.lineup.includes(c.captain))c.captain=c.lineup[0];if(!c.lineup.includes(c.setPiece))c.setPiece=c.lineup[10];}
function pitchBoard(c){return `<div class="pitch-board" style="--club-color:${c.color}"><span class="pitch-circle"></span><span class="pitch-box"></span><span class="pitch-box bottom"></span>${formationPoints(c.tactics.formation).map(([x,y],i)=>{const p=E.player(state,c.lineup[i]);return `<span class="pitch-player" style="left:${x*100}%;top:${y*100}%"><span class="pitch-shirt">${i+1}</span><small>${esc(p?.name.split(' ').at(-1)||'Vacant')}</small></span>`;}).join('')}</div>`;}
function tacticFields(t,live=false){return `${stylePicker(t,live)}<div class="tactic-controls">${field('Formation',`<select data-tactic="formation" ${!live&&state.activeMatch?'disabled':''}>${options(Object.keys(E.FORMATIONS),t.formation)}</select>`)}${Object.entries(E.OPTIONS).map(([k,values])=>field(title(k),`<select data-tactic="${k}" ${!live&&state.activeMatch?'disabled':''}>${options(values,t[k])}</select>`)).join('')}</div>`;}
function tacticsView(){const c=myClub();return `${heading('Find your edge.', 'A clear idea. Eleven players. One shared purpose.',`<span class="tag green">${esc(c.tactics.formation)} · ${esc(styleName(c.tactics))}</span>`)}<div class="grid halves tactic-grid"><section class="panel"><div class="panel-head"><h2>Shape on the pitch</h2><span class="tag">${esc(c.tactics.formation)}</span></div><div class="panel-body">${pitchBoard(c)}<div class="legend"><span>● Starting XI</span><span>Roles affect team strengths</span></div></div></section><div class="grid"><section class="panel"><div class="panel-head"><h2>Team instructions</h2><span class="small muted">Autosaved</span></div><div class="panel-body">${tacticFields(c.tactics)}<p class="help">High pressing wins more territory but uses more fitness. A high line can expose you to fast direct attacks. Short passing favors control; wide play creates space against narrow teams. Attacking mentality trades defensive security for chances.</p></div></section><section class="panel"><div class="panel-head"><h2>Player roles</h2><span class="small muted">Starting XI</span></div><div class="panel-body">${c.lineup.filter(Boolean).map(id=>{const p=E.player(state,id);return `<label class="lineup-item" style="grid-template-columns:1fr 130px"><span class="small">${esc(p.name)} <span class="tiny muted">${p.primaryPosition}</span></span><select data-role="${esc(id)}" aria-label="Role for ${esc(p.name)}" ${state.activeMatch?'disabled':''}>${options(E.ROLES[p.position],p.role)}</select></label>`;}).join('')}<p class="help">Playmakers help possession, anchors protect the defense, and wing backs add attacking threat. A target forward benefits from direct passing.</p></div></section></div></div>`;}
function bindTactics(){app.querySelector('[data-style]').onchange=e=>runAction(()=>E.setTacticalStyle(state,e.target.value));app.querySelectorAll('[data-tactic]').forEach(el=>el.onchange=()=>runAction(()=>{if(state.activeMatch)throw Error('Change tactics in the match centre.');const c=myClub();c.tactics[el.dataset.tactic]=el.value;if(el.dataset.tactic==='formation')E.autoLineup(state,c);}));app.querySelectorAll('[data-role]').forEach(el=>el.onchange=()=>runAction(()=>{if(state.activeMatch)throw Error('Roles are locked during a match.');E.player(state,el.dataset.role).role=el.value;},false));}
function transfersView(){const c=myClub(),rows=state.players.filter(p=>p.clubId!==c.id&&(!transferFilter||p.name.toLowerCase().includes(transferFilter.toLowerCase()))&&(!transferPos||p.position===transferPos)&&(!transferClub||p.clubId===transferClub)).sort((a,b)=>rating(b)-rating(a));return `${heading('Build for tomorrow.', 'Scout a prospect. Negotiate a deal. Give them a new home.',`<span class="tag green">${compactMoney(c.balance)} available cash</span>`)}<div class="notice">${state.league.transferRules.window==='preseason'&&state.round!==0?'Transfer window closed. Scouting remains available.':'Negotiate one offer per player per week. Selling clubs protect squad depth; players consider reputation, wages, and contract length.'} Scouting costs ${money(state.league.transferRules.scoutingCost)}. Keep ${state.league.transferRules.wageReserveWeeks} weeks of a new player’s wage in reserve.</div><div class="toolbar"><input id="transfer-search" placeholder="Search the market…" aria-label="Search transfer market" value="${esc(transferFilter)}"><select id="transfer-pos" aria-label="Filter transfer position">${option('','All positions',transferPos)}${options(['GK','DEF','MID','FWD'],transferPos)}</select><select id="transfer-club" aria-label="Filter transfer club">${option('','All clubs',transferClub)}${state.clubs.filter(t=>t.id!==c.id).map(t=>option(t.id,t.name,transferClub)).join('')}</select><span class="small muted">${rows.length} players</span></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Player</th><th>Club</th><th>Pos</th><th>Age</th><th>Ability / Pot</th><th>Asking price</th><th>Wage / wk</th><th>Actions</th></tr></thead><tbody>${rows.slice(0,100).map(p=>{const scouted=state.scouted.includes(p.id);return `<tr><td><button class="text-btn" data-player="${esc(p.id)}">${esc(p.name)}</button><div class="tiny muted">${p.injury?`Injured · ${p.injury} weeks`:scouted?'Report available':'Unscouted'}</div></td><td><div class="team-name">${crest(E.club(state,p.clubId),'sm')}${esc(E.club(state,p.clubId).short)}</div></td><td><span class="tag">${p.primaryPosition}</span></td><td>${p.age}</td><td>${scouted?`${badge(rating(p))} <span class="gold small">/ ${p.potential}</span>`:`<span class="muted">${Math.floor(rating(p)/10)*10}–${Math.min(99,Math.floor(rating(p)/10)*10+9)} / ?</span>`}</td><td>${compactMoney(E.marketPrice(state,p))}</td><td class="muted">${money(p.wage)}</td><td><div class="actions">${!scouted?`<button class="btn sm" data-scout="${esc(p.id)}" ${state.activeMatch?'disabled':''}>Scout</button>`:''}<button class="btn sm primary" data-bid="${esc(p.id)}" ${state.activeMatch?'disabled':''}>Offer</button></div></td></tr>`;}).join('')||'<tr><td colspan="8" class="empty">No matching players.</td></tr>'}</tbody></table></div>${rows.length>100?'<div class="panel-body help">Showing the top 100 matches. Filter by club or position to narrow your search.</div>':''}</section>`;}
function bindTransfers(){for(const [id,set] of [['transfer-search',v=>transferFilter=v],['transfer-pos',v=>transferPos=v],['transfer-club',v=>transferClub=v]])app.querySelector('#'+id).onchange=e=>{set(e.target.value);render();};app.querySelectorAll('[data-scout]').forEach(b=>b.onclick=()=>runAction(()=>{E.scout(state,b.dataset.scout);toast('Scout report ready.');}));app.querySelectorAll('[data-bid]').forEach(b=>b.onclick=()=>bidForm(b.dataset.bid));}
function bidForm(id){const p=E.player(state,id);const d=showModal(`Negotiate: ${p.name}`,`<form id="bid-form"><div class="modal-body"><div class="player-identity">${crest(E.club(state,p.clubId),'large')}<div><h2>${esc(p.name)}</h2><p class="muted small">${p.age} years · ${p.primaryPosition} · ${esc(E.club(state,p.clubId).name)}</p><p class="small">Asking price: <strong class="positive">${money(E.marketPrice(state,p))}</strong></p></div></div><div class="field-grid">${field('Transfer fee (£)',numberInput('fee',E.marketPrice(state,p)))}${field('Weekly wage (£)',numberInput('wage',E.negotiationWage(state,p),100,1000000))}${field('Contract length (years)',`<select name="years">${[1,2,3,4].map(n=>option(String(n),`${n} year${n>1?'s':''}`,'3')).join('')}</select>`)}</div><p class="help">Fees move between clubs only when both the selling club and player agree. Asking prices are negotiable. A rejected offer uses this week’s negotiation opportunity.</p><div id="bid-error"></div></div><div class="modal-footer"><button class="btn primary" type="submit">Submit offer</button></div></form>`);d.querySelector('form').onsubmit=e=>{e.preventDefault();try{const fd=new FormData(e.target),result=E.transfer(state,id,Number(fd.get('fee')),Number(fd.get('wage')),Number(fd.get('years')));save();render();d.close();toast(result.message,!result.ok);}catch(err){d.querySelector('#bid-error').innerHTML=errorsHTML([err.message]);}};}
function trainingView(){const roster=E.squad(state,state.userClubId);const descriptions={Balanced:'A little of everything. Passing, touch, decisions, and more.',Attacking:'Finishing, composure, dribbling, and technique.',Defending:'Defensive work, marking, tackling, and goalkeeping.',Fitness:'Stamina, pace, strength, and acceleration.'};return `${heading('Small gains. Big difference.', 'Training happens once per matchweek, alongside recovery and player development.')}<div class="grid halves"><section class="panel"><div class="panel-head"><h2>Weekly focus</h2><span class="tag green">${state.training}</span></div><div class="panel-body"><div class="training-options">${Object.entries(descriptions).map(([name,text])=>`<button class="training-card ${state.training===name?'selected':''}" data-training="${name}" ${state.activeMatch?'disabled':''}><strong>${name}</strong><p>${text}</p></button>`).join('')}</div><div style="margin-top:22px">${field('Training intensity',`<select id="training-intensity" ${state.activeMatch?'disabled':''}>${options(['Normal','Intense','Rest'],state.trainingIntensity)}</select>`)}</div><p class="help">Intense training develops players faster but reduces recovery and carries injury risk. Rest restores fitness and morale, without development. Young players improve faster; attributes stop growing once calculated ability reaches potential.</p></div></section><section class="panel"><div class="panel-head"><h2>Medical room</h2><span class="tag">${roster.filter(p=>p.injury).length} unavailable</span></div><div class="panel-body">${roster.filter(p=>p.injury).map(p=>`<div class="finance-row"><button class="text-btn" data-player="${esc(p.id)}">${esc(p.name)}</button><span class="gold">${p.injury} week${p.injury>1?'s':''}</span></div>`).join('')||'<p class="positive small">A clean bill of health. Everyone is available.</p>'}<p class="help">Injured players recover weekly. Match knocks reduce effectiveness immediately; substitute them to protect performance. Your medical team handles recovery automatically.</p></div></section></div><section class="panel" style="margin-top:20px"><div class="panel-head"><h2>Development watch</h2><span class="small muted">Youth and potential</span></div><div class="table-wrap"><table><thead><tr><th>Player</th><th>Age</th><th>Ability</th><th>Potential</th><th>Next gain progress</th><th>Fitness</th><th>Morale</th></tr></thead><tbody>${[...roster].sort((a,b)=>a.age-b.age).map(p=>`<tr><td><button class="text-btn" data-player="${esc(p.id)}">${esc(p.name)}</button></td><td>${p.age}</td><td>${badge(rating(p))}</td><td class="gold">${p.potential}</td><td><span class="fit"><span class="meter"><i style="width:${Math.min(100,p.development*100)}%"></i></span>${Math.round(p.development*100)}%</span></td><td>${fit(p)}</td><td>${Math.round(p.morale)}</td></tr>`).join('')}</tbody></table></div></section>`;}
function bindTraining(){app.querySelectorAll('[data-training]').forEach(b=>b.onclick=()=>runAction(()=>state.training=b.dataset.training));app.querySelector('#training-intensity').onchange=e=>runAction(()=>state.trainingIntensity=e.target.value);}
function leagueView(){const rows=E.standings(state);leagueRound=Math.min(leagueRound,state.fixtures.length-1);return `${heading(esc(state.league.name),`Season ${state.season} · ${state.clubs.length} clubs · ${state.fixtures.length} matchweeks`, `<span class="tag">${state.league.schedule.legs} LEG ROUND ROBIN</span>`)}<div class="league-tabs">${['table','fixtures','statistics','history'].map(t=>`<button class="tab ${leagueTab===t?'active':''}" data-league-tab="${t}">${title(t)}</button>`).join('')}</div>${leagueTab==='table'?`<section class="panel">${table(rows)}</section><p class="help">Ranked by points, goal difference, goals scored, then club name. Three points for a win, one for a draw. All teams play each other ${state.league.schedule.legs} times. No promotion/relegation is active in this league.</p>`:leagueTab==='fixtures'?`<div class="toolbar"><button class="btn sm" data-round-step="-1" ${leagueRound===0?'disabled':''}>← Previous</button><select id="league-round" aria-label="Fixture matchweek">${state.fixtures.map((_,r)=>option(String(r),`Matchweek ${r+1}`,String(leagueRound))).join('')}</select><button class="btn sm" data-round-step="1" ${leagueRound===state.fixtures.length-1?'disabled':''}>Next →</button></div><section class="panel"><div class="panel-head"><h2>Matchweek ${leagueRound+1}</h2><span class="tag">${leagueRound<state.round?'PLAYED':'UPCOMING'}</span></div>${state.fixtures[leagueRound].map(f=>`<div class="fixture-row"><div class="team-name grow">${crest(E.club(state,f.home),'sm')}${esc(E.club(state,f.home).name)}</div><strong style="min-width:65px;text-align:center">${f.result?f.result.score.join(' – '):'vs'}</strong><div class="team-name grow" style="justify-content:flex-end">${esc(E.club(state,f.away).name)}${crest(E.club(state,f.away),'sm')}</div>${f.result?`<button class="btn sm" data-result="${esc(f.id)}">Stats</button>`:''}</div>`).join('')}</section>`:leagueTab==='statistics'?`<div class="grid halves">${[['goals','Golden boot'],['assists','Creative force']].map(([key,name])=>`<section class="panel"><div class="panel-head"><h2>${name}</h2><span class="tag">${title(key)}</span></div><div class="table-wrap"><table><thead><tr><th>Player</th><th>Club</th><th>Apps</th><th>${title(key)}</th></tr></thead><tbody>${[...state.players].sort((a,b)=>b[key]-a[key]||a.name.localeCompare(b.name)).slice(0,15).map(p=>`<tr><td><button class="text-btn" data-player="${esc(p.id)}">${esc(p.name)}</button><div class="tiny muted">${p.primaryPosition}</div></td><td>${esc(E.club(state,p.clubId).short)}</td><td class="muted">${p.appearances}</td><td class="positive"><strong>${p[key]}</strong></td></tr>`).join('')}</tbody></table></div></section>`).join('')}</div>`:`<section class="panel"><div class="panel-head"><h2>The record books</h2></div>${state.history.length?state.history.slice().reverse().map(h=>`<div class="panel-body"><h3>Season ${h.season} · ${esc(h.table[0].name)} champions</h3><p class="muted small">${h.table[0].points} points · Top scorer: ${esc(h.topScorer)}</p></div>`).join(''):'<div class="empty">Complete a season and begin the next to archive your results.</div>'}</section>`}`;}
function bindLeague(){app.querySelectorAll('[data-league-tab]').forEach(b=>b.onclick=()=>{leagueTab=b.dataset.leagueTab;leagueRound=Math.min(state.round,state.fixtures.length-1);render();});app.querySelectorAll('[data-round-step]').forEach(b=>b.onclick=()=>{leagueRound+=Number(b.dataset.roundStep);render();});const sel=app.querySelector('#league-round');if(sel)sel.onchange=()=>{leagueRound=Number(sel.value);render();};app.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>{const f=state.fixtures.flat().find(f=>f.id===b.dataset.result),r=f.result;showModal('Match report',`<div class="modal-body"><h2>${esc(E.club(state,f.home).name)} ${r.score.join(' – ')} ${esc(E.club(state,f.away).name)}</h2><div style="margin-top:25px">${statsHTML(r,E.club(state,f.home),E.club(state,f.away),r.possession)}</div><h3 style="margin-top:20px">Goalscorers</h3><p class="small muted" style="margin-top:8px">${Object.entries(r.goals).map(([id,n])=>`${esc(E.player(state,id)?.name||id)} (${n})`).join(' · ')||'No goals'}</p></div>`);});}
function financeView(){const c=myClub(),roster=E.squad(state,c.id),wages=roster.reduce((sum,p)=>sum+p.wage,0);return `${heading('Beyond the touchline.', 'Keep the books balanced and the board on your side.')}<div class="stats"><div class="stat"><div class="label">Cash balance</div><div class="value ${c.balance<0?'negative':'positive'}">${compactMoney(c.balance)}</div><div class="foot">Editor budgets count as ledger adjustments</div></div><div class="stat"><div class="label">Total income</div><div class="value">${compactMoney(c.income)}</div><div class="foot">Matchdays, sponsors, sales, prizes</div></div><div class="stat"><div class="label">Total expenses</div><div class="value">${compactMoney(c.expenses)}</div><div class="foot">Wages, operations, signings, scouting</div></div><div class="stat"><div class="label">Weekly wage bill</div><div class="value">${compactMoney(wages)}</div><div class="foot">${roster.length} contracted players</div></div></div><div class="grid halves"><section class="panel"><div class="panel-head"><h2>Boardroom</h2><button class="btn sm" data-action="edit-career-league">Edit league rules</button></div><div class="panel-body"><div class="board-summary"><span class="board-ring">${state.boardConfidence}%</span><div><h3>${state.boardConfidence>=65?'Backing your vision':state.boardConfidence>=40?'Room for improvement':'Results need to improve'}</h3><p class="muted small">Season expectation: ${esc(boardGoal(state,c))} · ${state.difficulty}</p></div></div><p class="muted small">The board reviews your league position weekly. Confidence is advisory in this version; you can finish your career without dismissal.</p><div class="finance-row"><span>Sponsorship / week</span><span class="positive">${money(state.league.finance.sponsorship)}</span></div><div class="finance-row"><span>Operations / week</span><span>${money(state.league.finance.operations)}</span></div><div class="finance-row"><span>Wages / week</span><span>${money(wages)}</span></div></div></section><section class="panel"><div class="panel-head"><h2>Club identities</h2><span class="tag">CAREER EDITOR</span></div><div class="panel-body"><p class="muted small" style="margin-bottom:15px">Change club names, colors, and budgets inside this save. Bundled files and the database studio stay separate.</p>${state.clubs.map(t=>`<div class="finance-row"><span class="team-name">${crest(t,'sm')}${esc(t.name)}</span><button class="btn sm" data-career-club="${esc(t.id)}">Edit</button></div>`).join('')}</div></section></div><section class="panel" style="margin-top:20px"><div class="panel-head"><h2>Finance ledger</h2><span class="small muted">Your most recent transactions</span></div><div class="table-wrap"><table><thead><tr><th>Season / Week</th><th>Description</th><th class="right">Amount</th></tr></thead><tbody>${state.ledger.filter(l=>l.clubId===c.id).slice(0,40).map(l=>`<tr><td class="muted">${l.season} / ${l.round+1}</td><td>${esc(l.reason)}</td><td class="right ${l.amount>0?'positive':'negative'}">${l.amount>0?'+':''}${money(l.amount)}</td></tr>`).join('')||'<tr><td colspan="3" class="empty">No transactions yet. Your first matchweek settles wages and revenue.</td></tr>'}</tbody></table></div></section><p class="help">Contracts tick down at season end. Expiring players receive a one-year bridge contract with an 8% wage rise; renew them manually via their player profile. Negative cash is allowed, but transfers require funds.</p>`;}
function bindFinance(){app.querySelectorAll('[data-career-club]').forEach(b=>b.onclick=()=>careerClubForm(b.dataset.careerClub));}
function careerClubForm(id){const c=E.club(state,id);const d=showModal('Edit career club',`<form><div class="modal-body"><p class="muted small" style="margin-bottom:20px">Stable ID: ${esc(c.id)} · Changes apply only to this career.</p><div class="field-grid">${field('Club name',`<input name="name" value="${esc(c.name)}" required maxlength="60">`)}${field('Abbreviation',`<input name="short" value="${esc(c.short)}" required maxlength="4">`)}${field('Color',`<input type="color" name="color" value="${c.color}">`)}${field('Cash budget (£)',numberInput('balance',c.balance))}</div><div id="career-club-error"></div></div><div class="modal-footer"><button class="btn primary" type="submit">Save club</button></div></form>`);d.querySelector('form').onsubmit=e=>{e.preventDefault();try{const fd=new FormData(e.target);E.editClub(state,id,{name:fd.get('name'),short:fd.get('short'),color:fd.get('color'),balance:Number(fd.get('balance'))});save();render();d.close();toast('Club updated in your career.');}catch(err){d.querySelector('#career-club-error').innerHTML=errorsHTML([err.message]);}};}
function careerLeagueForm(){const d=showModal('Edit career league',`<form><div class="modal-body"><p class="notice">Schedule changes are allowed before matchweek one only. Names and transfer rules can change between matches.</p>${leagueFields(state.league)}<div id="career-league-error"></div></div><div class="modal-footer"><button class="btn primary" type="submit">Save league rules</button></div></form>`);d.querySelector('form').onsubmit=e=>{e.preventDefault();try{E.editLeague(state,readLeagueForm(e.target,state.league));save();render();d.close();toast('League settings saved.');}catch(err){d.querySelector('#career-league-error').innerHTML=errorsHTML([err.message]);}};}
function statsHTML(m,h,a,pos){return `<div class="match-stats" style="--home:${h.color};--away:${a.color}">${[['Possession',pos,v=>`${v}%`],['Shots',m.shots,String],['On target',m.onTarget,String],['Expected goals',m.xg,v=>v.toFixed(2)],['Yellow cards',m.yellowCards||(m.cards?m.teams.map((_,side)=>m.used[side].reduce((sum,id)=>sum+(m.cards.yellow[id]||0),0)):[0,0]),String]].map(([name,vals,fmt])=>`<div class="match-stat-row"><span>${fmt(vals[0])}</span><div><div class="stat-name">${name}</div><div class="bar"><i style="width:${vals[0]+vals[1]?vals[0]/(vals[0]+vals[1])*100:50}%"></i><i style="flex:1"></i></div></div><span>${fmt(vals[1])}</span></div>`).join('')}</div>`;}
function matchView(){const m=state.activeMatch;if(!m)return dashboard();const h=E.club(state,m.teams[0]),a=E.club(state,m.teams[1]),side=m.teams.indexOf(state.userClubId);return `${heading('The match centre.', `${esc(h.stadium)} · Matchweek ${state.round+1} · Seeded minute-by-minute simulation`, '<span class="tag green">LIVE EVENT VIEW</span>')}<div class="match-header"><div class="team">${crest(h,'large')}<span>${esc(h.name)}${side===0?'<div class="tiny positive">YOUR CLUB</div>':''}</span></div><div><div class="scoreline" id="match-score">${m.score.join(' : ')}</div><div class="match-clock" id="match-clock">${clockLabel(m)}</div></div><div class="team away"><span>${esc(a.name)}${side===1?'<div class="tiny positive">YOUR CLUB</div>':''}</span>${crest(a,'large')}</div></div><div class="match-layout"><div><div class="match-stage"><canvas id="match-pitch" aria-label="Animated 2D event view of the match"></canvas><div id="event-banner" class="event-banner">${esc(m.lastEvent?.text)}</div><div class="match-controls"><button class="btn primary" id="pause-play" ${m.done?'disabled':''}>${icon(playing?'pause':'play')}${playing?'Pause':m.phase==='halftime'?'Start second half':'Play'}</button><select id="match-speed" aria-label="Match speed">${[1,2,4,8].map(n=>option(String(n),`${n}× speed`,String(speed))).join('')}</select><button class="btn" id="instant" ${m.done?'disabled':''}>Instant result</button><button class="btn ghost" data-go="dashboard">Save & leave</button>${m.done?'<button class="btn primary" id="commit-result">Continue →</button>':''}</div></div><div id="live-assistant">${assistantPanel()}</div><div class="panel match-management"><div class="panel-head"><h2>Your decisions</h2><span class="small muted">${m.subs[side]} / 5 substitutions</span></div><div class="panel-body"><div class="notice ${m.done?'':'warn'}">${m.done?'Match complete. Continue to settle all league fixtures, wages, training, and standings.':'Pause to make changes. Tactical instructions and substitutions affect the remaining minutes.'}</div>${tacticFields(m.tactics[side],true)}<h3 style="margin-top:22px">Substitutions</h3><div class="field-grid" style="margin-top:12px">${field('Player off',`<select id="sub-out" ${m.done?'disabled':''}>${m.lineups[side].map(id=>{const p=E.player(state,id);return option(id,`${p.name} · ${Math.round(m.fitness[id])}%${m.knocks.includes(id)?' · KNOCK':''}`,null);}).join('')}</select>`)}${field('Player on',`<select id="sub-in" ${m.done?'disabled':''}>${m.bench[side].map(id=>{const p=E.player(state,id);return option(id,`${p.name} · ${p.primaryPosition} · ${rating(p)}`,null);}).join('')}</select>`)}</div><button class="btn" id="make-sub" style="margin-top:12px" ${m.done||m.subs[side]>=5||!m.bench[side].length?'disabled':''}>Make substitution</button><p class="help">The pitch is an animated illustration of events, not a physics engine. Commentary, goals, shots, possession, and xG come directly from the same simulation events. A match lasts 90 minutes with a half-time break.</p></div></div></div><div class="match-side"><section class="panel"><div class="panel-head"><h2>Match statistics</h2><span class="tag">${h.short} / ${a.short}</span></div><div class="panel-body" id="match-stats">${statsHTML(m,h,a,E.possession(m))}</div></section><section class="panel" style="margin-top:18px"><div class="panel-head"><h2>From the touchline</h2><span class="tag">COMMENTARY</span></div><div class="commentary" id="commentary">${commentaryHTML(m)}</div></section></div></div>`;}
function clockLabel(m){return `${m.minute}′ · ${m.done?'FULL TIME':m.phase==='halftime'?'HALF TIME':playing?'LIVE':'PAUSED'}`;}
function commentaryHTML(m){return m.events.slice().reverse().map(e=>`<div class="comment ${esc(e.type)}"><span class="minute">${e.minute}′</span><span>${esc(e.text)}</span></div>`).join('');}
function updateMatch(){const m=state.activeMatch;if(view!=='match'||!m)return;app.querySelector('#match-score').textContent=m.score.join(' : ');app.querySelector('#match-clock').textContent=clockLabel(m);app.querySelector('#event-banner').textContent=m.lastEvent.text;app.querySelector('#match-stats').innerHTML=statsHTML(m,E.club(state,m.teams[0]),E.club(state,m.teams[1]),E.possession(m));app.querySelector('#commentary').innerHTML=commentaryHTML(m);const b=app.querySelector('#pause-play');b.innerHTML=`${icon(playing?'pause':'play')}${playing?'Pause':m.phase==='halftime'?'Start second half':'Play'}`;
  if(m.minute%5===0){save();const assistant=app.querySelector('#live-assistant');if(assistant){assistant.innerHTML=assistantPanel();assistant.querySelector('[data-action="ask-assistant"]').onclick=askAssistant;}}if(m.done||m.phase==='halftime'){pause();save();render();if(m.phase==='halftime')toast('Half-time. Adjust your tactics or make a substitution, then start the second half.');}
}
function startClock(){clearInterval(timer);if(!playing||state.activeMatch?.done)return;timer=setInterval(()=>{if(view!=='match'||document.hidden){pause();save();return;}try{E.stepMatch(state,state.activeMatch);updateMatch();}catch(e){pause();toast(e.message,true);}},[0,1000,450,180,75][[0,1,2,4,8].indexOf(speed)]||450);}
function bindMatch(){const m=state.activeMatch,side=m.teams.indexOf(state.userClubId);
  const off=app.querySelector('#sub-out'),on=app.querySelector('#sub-in');
  const tired=[...m.lineups[side].slice(1)].sort((a,b)=>(m.knocks.includes(b)?1:0)-(m.knocks.includes(a)?1:0)||m.fitness[a]-m.fitness[b])[0];
  if(tired)off.value=tired;
  app.querySelector('[data-style]').disabled=m.done;app.querySelector('[data-style]').onchange=e=>runAction(()=>{pause();E.changeMatchStyle(m,side,e.target.value);myClub().tactics={...m.tactics[side]};});
  const selectReplacement=()=>{const outgoing=E.player(state,off.value);const same=m.bench[side].find(id=>E.player(state,id).position===outgoing?.position);if(same)on.value=same;};selectReplacement();off.onchange=selectReplacement;
app.querySelector('#pause-play').onclick=()=>{if(playing)pause();else{E.resumeMatch(m);playing=true;startClock();}save();updateMatch();};app.querySelector('#match-speed').onchange=e=>{speed=Number(e.target.value);if(playing)startClock();};app.querySelector('#instant').onclick=()=>runAction(()=>{pause();E.simulateMatch(state,m);});const commit=app.querySelector('#commit-result');if(commit)commit.onclick=()=>runAction(()=>{pause();E.finishRound(state);view='dashboard';});app.querySelectorAll('[data-tactic]').forEach(el=>{el.disabled=m.done;el.onchange=()=>runAction(()=>{pause();E.changeMatchTactic(m,side,el.dataset.tactic,el.value);myClub().tactics[el.dataset.tactic]=el.value;});});app.querySelector('#make-sub').onclick=()=>runAction(()=>{pause();E.substitute(state,m,side,app.querySelector('#sub-out').value,app.querySelector('#sub-in').value);});}
function showPlayer(id){const p=E.player(state,id);if(!p)return;const own=p.clubId===state.userClubId,scouted=own||state.scouted.includes(id);const d=showModal(p.name,`<div class="modal-body"><div class="player-identity"><div class="avatar">${esc(p.name.split(' ').map(n=>n[0]).slice(0,2).join(''))}</div><div><h2>${esc(p.name)} ${scouted?badge(rating(p)):''}</h2><p class="muted small">${esc(E.club(state,p.clubId).name)} · ${p.primaryPosition}${p.secondaryPositions.length?' / '+esc(p.secondaryPositions.join(' / ')):''} · ${p.age} years</p><p class="muted small">${esc(p.nationality)} · ${p.preferredFoot} foot · ${esc(p.id)}</p></div></div><div class="grid three" style="margin-bottom:24px"><div><span class="muted small">Weekly wage</span><p>${money(p.wage)}</p></div><div><span class="muted small">Contract</span><p>${p.contract} years remaining</p></div><div><span class="muted small">Potential</span><p class="gold">${scouted?p.potential:'Scout to reveal'}</p></div></div><div class="grid halves" style="margin-bottom:20px"><div>Fitness ${fit(p)}</div><div class="small">Morale: ${Math.round(p.morale)} / 100${p.injury?` · <span class="negative">Injured ${p.injury} weeks</span>`:''}</div></div>${scouted?`<div class="attribute-grid">${Object.entries(ATTRIBUTES).map(([group,keys])=>`<section class="attribute-section"><h3>${group}</h3>${keys.map(k=>`<div class="attr-row"><span>${LABELS[k]||title(k)}</span><span class="attr-value">${p[k]}</span></div>`).join('')}</section>`).join('')}</div>`:`<div class="notice">Scout this player for an exact attribute and potential report. Estimated ability: ${Math.floor(rating(p)/10)*10}–${Math.min(99,Math.floor(rating(p)/10)*10+9)}.</div>`}<p class="help">This season: ${p.appearances} appearances · ${p.minutes} minutes · ${p.goals} goals · ${p.assists} assists · ${p.shots} shots · ${p.yellowCards} yellow cards. ${p.form?.length?`Recent match form: ${p.form.map(n=>n.toFixed(1)).join(' · ')} / 10.`:''}</p>${own?`<h3 style="margin-top:20px">Renew contract</h3><form id="renew-form" class="field-grid" style="margin-top:15px">${field('Years',`<select name="years">${options(['1','2','3','4'],'3')}</select>`)}${field('Weekly wage (£)',numberInput('wage',Math.round(p.wage*1.1/100)*100,100,1000000))}<button class="btn" type="submit" ${state.activeMatch?'disabled':''}>Offer renewal</button><button class="btn danger" type="button" id="sell-profile" ${state.activeMatch?'disabled':''}>Find buyer · ${compactMoney(E.playerValue(p))}</button></form>`:''}</div>`);
  const renewal=d.querySelector('#renew-form');if(renewal)renewal.onsubmit=e=>{e.preventDefault();try{const fd=new FormData(e.target);E.renewContract(state,id,Number(fd.get('years')),Number(fd.get('wage')));save();render();d.close();toast('Contract renewed.');}catch(err){toast(err.message,true);}};
  const sell=d.querySelector('#sell-profile');if(sell)sell.onclick=()=>confirmAction('Sell player?',`Accept ${money(E.playerValue(p))} for ${p.name}? An AI buyer will take over their wages and contract.`,()=>{E.sellPlayer(state,id);save();render();toast('Player sold.');});
}
function continueGame(){if(state.activeMatch){navigate('match');return;}if(state.round===state.fixtures.length){confirmAction('Begin a new season?', 'Archive this season, award no additional prizes, and start a new schedule. Players age by one year and contracts tick down. Your club and finances carry forward.',()=>{E.nextSeason(state);save();view='dashboard';render();});return;}if(!E.nextFixture(state)){runAction(()=>E.finishRound(state));return;}const error=E.validateLineup(state,myClub());if(error){navigate('squad');toast(error,true);return;}runAction(()=>{E.startMatch(state);playing=false;view='match';});}
function bindCommon(){app.querySelectorAll('[data-style-help]').forEach(b=>b.onclick=showStyleHelp);app.querySelectorAll('[data-go]').forEach(b=>b.onclick=e=>{e.preventDefault();navigate(b.dataset.go);});app.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{const action=b.dataset.action;try{
  if(action==='ask-assistant')askAssistant();
  else if(action==='continue')continueGame();
  else if(action==='export-save'){save();download(`touchline-season-${state.season}-week-${state.round+1}.json`,E.serialize(state));toast('Career exported, including any match in progress.');}
  else if(action==='import-save')importSave();
  else if(action==='new-career'){if(!state){view='selection';render();}else confirmAction('Start a new career?', 'Your current local career will be replaced when you choose a club. Export it first if you want to keep it. The editor database remains.',()=>{pause();state=null;view='selection';render();});}
  else if(action==='auto-lineup')runAction(()=>{if(state.activeMatch)throw Error('Selection is locked during the match.');E.autoLineup(state,myClub());toast('Best available XI selected.');});
  else if(action==='edit-career-league')careerLeagueForm();
  else if(action==='help')help();
}catch(e){toast(e.message,true);}});app.querySelectorAll('[data-player]').forEach(b=>b.onclick=()=>showPlayer(b.dataset.player));}
function importSave(){pause();pickFile('.json',text=>{const loaded=E.deserialize(text);confirmAction('Load exported career?', `Replace your local career with ${E.club(loaded,loaded.userClubId).name}, season ${loaded.season}, week ${loaded.round+1}? Export your current career first if needed.`,()=>{state=loaded;view=loaded.activeMatch?'match':'dashboard';save();render();toast('Career loaded. Any live match resumes paused.');});});}
function renderSelection(){const source=customDB?getEditorDatabase():db;if(!source.leagues.some(l=>l.id===chosenLeague))chosenLeague=source.leagues[0].id;const league=source.leagues.find(l=>l.id===chosenLeague),clubs=source.clubs.filter(c=>league.teamIds.includes(c.id));app.innerHTML=`<main class="selection"><header class="selection-header"><div class="brand"><img src="./assets/crest.svg" alt=""><div>TOUCHLINE<br><span>TWELVE</span></div></div><div class="actions"><button class="btn ghost" data-go="editor">${icon('editor')} Database studio</button><button class="btn" data-action="import-save">Import career</button>${localStorage.getItem(SAVE_KEY)?'<button class="btn" data-resume>Resume saved career</button>':''}</div></header><div class="intro"><div class="eyebrow">A fresh season. A new story.</div><h1>Every club has a story.<br><em>Make one yours.</em></h1><p>A full season of football, built for a few minutes at a time. Pick your club, shape your squad, and take your place on the touchline.</p></div><div class="toolbar"><select id="choose-league" aria-label="Choose league">${source.leagues.map(l=>option(l.id,`${l.name} · ${l.teamIds.length} clubs`,chosenLeague)).join('')}</select><label class="field" style="flex-direction:row;align-items:center"><input type="checkbox" id="use-editor" ${customDB?'checked':''}>Use my edited database</label><label class="field" style="flex-direction:row;align-items:center">Career seed <input id="career-seed" style="width:110px" type="number" min="0" max="4294967295" value="${careerSeed}"></label><span class="muted small">${clubs.length} clubs · ${league.schedule.legs} legs · ${customDB?'Your editor database':'Bundled roster'}</span></div><div class="difficulty-grid" aria-label="Career difficulty">${Object.entries(DIFFICULTIES).map(([name,settings])=>`<label class="difficulty-card ${careerDifficulty===name?'selected':''}"><div><input type="radio" name="career-difficulty" value="${name}" ${careerDifficulty===name?'checked':''}><strong>${name}</strong>${name==='Medium'?'<span class="tag">RECOMMENDED</span>':''}</div><p>${esc(settings.description)}</p></label>`).join('')}</div><p class="help" style="margin-bottom:22px">Same player attributes and match rules on every difficulty. Only management pressure and opponent decisions change. Difficulty stays fixed for this career.</p><div class="club-grid">${clubs.map(c=>`<button class="club-card" data-select-club="${esc(c.id)}" style="--club-color:${c.color}"><div class="club-card-top">${crest(c,'large')}<div><h2>${esc(c.name)}</h2><span class="tiny muted">${esc(c.stadium)}</span></div></div><p>${esc(c.identity)}</p><div class="club-card-meta"><span>${compactMoney(c.balance)} budget</span><strong>${esc(boardGoal({difficulty:careerDifficulty,clubs},c))}</strong></div><div class="tiny muted" style="margin-top:12px">${source.players.filter(p=>p.clubId===c.id).length} players · Reputation ${c.strength} <span style="float:right;color:var(--club-color)">Take charge →</span></div></button>`).join('')}</div><div class="page-footer"><span>LOCAL AUTOSAVE · NO ACCOUNT · NO AUDIO REQUIRED</span><button class="text-btn small muted" data-action="help">How to play →</button></div></main>`;
  bindCommon();app.querySelector('#career-seed').oninput=e=>careerSeed=Number(e.target.value);app.querySelectorAll('[name="career-difficulty"]').forEach(el=>el.onchange=()=>{careerDifficulty=el.value;renderSelection();});app.querySelector('#choose-league').onchange=e=>{chosenLeague=e.target.value;renderSelection();};app.querySelector('#use-editor').onchange=e=>{customDB=e.target.checked;renderSelection();};app.querySelectorAll('[data-select-club]').forEach(b=>b.onclick=()=>{try{const seed=Number(app.querySelector('#career-seed').value);if(!Number.isInteger(seed)||seed<0||seed>4294967295)throw Error('Seed must be a whole number from 0 to 4294967295.');const fresh=E.newGame(seed,b.dataset.selectClub,source,chosenLeague,careerDifficulty);state=fresh;view='dashboard';save();render();window.scrollTo({top:0});toast(`Welcome to ${myClub().name}. Your career is saved locally.`);}catch(e){toast(e.message,true);}});
  const resume=app.querySelector('[data-resume]');if(resume)resume.onclick=()=>{try{state=E.deserialize(localStorage.getItem(SAVE_KEY));view=state.activeMatch?'match':'dashboard';render();}catch(e){toast(e.message,true);}};
}
function help(){showModal('Welcome to your touchline',`<div class="modal-body"><div class="notice">A match takes about a minute at 2× speed. Pause, leave, and resume whenever you like.</div><div class="grid" style="gap:20px"><div><h3>1 · Build your XI</h3><p class="muted small">Use Squad to pick eleven starters and up to seven substitutes. Select a captain and set-piece taker. Auto pick is a useful starting point.</p></div><div><h3>2 · Give them a plan</h3><p class="muted small">Start with one of six styles under Tactics, then choose your formation, roles, and individual instructions. High pressing costs fitness. Position fit, morale, and player attributes matter.</p></div><div><h3>3 · Play and respond</h3><p class="muted small">Open the match centre and press Play. Pause to substitute (up to five) or change tactics. Half-time pauses automatically. Instant result completes the remaining minutes. Press Continue at full-time to update the league.</p></div><div><h3>4 · Manage the week</h3><p class="muted small">Training, recovery, wages, sponsorship, and AI transfers happen after the matchweek. Scout players and negotiate fees, wages, and contracts between matches.</p></div><div><h3>5 · Keep your story</h3><p class="muted small">Your career autosaves after actions and every five match minutes. Export it for backup or to move between browsers. Import validates the save before replacing it. Browser storage is local to this website and device.</p></div><div><h3>6 · Make it your world</h3><p class="muted small">Ask Assistant gives practical advice with an exact preview before any change. Database studio edits a separate local player, club, and league database. Export players.json to bundle it. Use your edited database for a new career, or explicitly migrate rosters before the first match of a season.</p></div></div></div>`);}
window.addEventListener('beforeunload',()=>{pause();save();});document.addEventListener('visibilitychange',()=>{if(document.hidden){pause();save();if(view==='match')updateMatch();}});document.addEventListener('keydown',e=>{if(e.code==='Space'&&view==='match'&&!['INPUT','SELECT','TEXTAREA','BUTTON'].includes(document.activeElement.tagName)&&!document.querySelector('#modal').open){e.preventDefault();document.querySelector('#pause-play')?.click();}});
async function boot(){try{db=await loadBundledDatabase();initEditor(db,render,()=>{customDB=true;if(state)toast('Your editor database is selected for the next career. Use New career when ready.');else {view='selection';render();toast('Your edited database is selected. Choose a club.');}},players=>{E.migratePlayers(state,players);save();render();toast('Career roster migrated explicitly.');});
    try{const text=localStorage.getItem(SAVE_KEY);if(text){state=E.deserialize(text);view=state.activeMatch?'match':'dashboard';}}
    catch(e){toast(`Saved career could not load: ${e.message}. Import a backup or start a new career.`,true);}render();
  }catch(e){app.innerHTML=`<main class="selection"><div class="eyebrow">Database could not load</div><h1>Check your data files.</h1>${errorsHTML([e.message])}<p class="muted">Run <code>npm start</code> from the project root. If you replaced your player database, check its clubs, IDs, and 1–99 attributes. Your existing browser save is untouched.</p><button class="btn primary" onclick="location.reload()" style="margin-top:20px">Retry</button></main>`;}}
boot();
function stylePicker(t,live=false){const selected=styleName(t),style=TACTICAL_STYLES[selected];return `<div class="style-picker"><div class="field-grid">${field('Simple tactical style',`<select data-style aria-label="Tactical style" ${!live&&state.activeMatch?'disabled':''}>${selected==='Custom'?'<option value="" selected disabled>Custom · manual instructions</option>':''}${Object.keys(TACTICAL_STYLES).map(name=>option(name,name,selected)).join('')}</select>`)}<div class="style-summary"><span class="tag green">${esc(selected)}</span><p class="small muted">${style?esc(style.description):'Your instructions differ from a preset. Pick a style to reset team instructions; your formation stays.'}</p></div></div>${style?`<div class="style-details"><p><strong>Suits</strong> ${esc(style.suits)}</p><p><strong>Strengths</strong> ${esc(style.strengths)}</p><p><strong>Tradeoff</strong> ${esc(style.weaknesses)}</p></div>`:''}<button class="text-btn small positive" data-style-help type="button">Compare all six styles →</button><p class="help">Presets keep your formation and lineup. Manual changes below show Custom when they differ from the selected style.</p></div>`;}
function assistantPanel(){const tips=proactiveAdvice(state);return `<section class="assistant-panel"><div class="assistant-avatar">${icon('squad')}</div><div class="assistant-copy"><div class="eyebrow">Assistant manager · ${state.difficulty}</div><p>${tips.length?esc(tips.map(t=>`${t.title}: ${t.reason}`).join(' ')):state.difficulty==='Hard'?'Your assistant is available whenever you ask. Review a plan before deciding.':'No urgent issue stands out. Ask for a squad plan, transfer shortlist, and opponent preview.'}</p></div><button class="btn sm" data-action="ask-assistant">Ask Assistant</button></section>`;}
function askAssistant(){pause();if(view==='match')render();state.assistant.lastAsked={season:state.season,round:state.round,minute:state.activeMatch?.minute??null};save();const recommendations=assistantAdvice(state);
  const body=`<div class="modal-body"><div class="notice">Advice uses your actual squad, recent form, current finances, and observed match state. Nothing changes until you review and apply a recommendation. Transfer suggestions never spend money.</div><div class="advice-list">${recommendations.map((rec,i)=>`<section class="advice-card"><div class="advice-title"><h3>${esc(rec.title)}</h3>${rec.important?'<span class="tag gold">PRIORITY</span>':''}</div><p>${esc(rec.reason)}</p><p class="tradeoff"><strong>Tradeoff</strong> ${esc(rec.tradeoff)}</p>${rec.action?`<button class="btn sm primary" data-review-advice="${i}">Apply recommendation…</button>`:'<span class="tiny muted">INFORMATION ONLY · NO AUTOMATIC ACTION</span>'}</section>`).join('')}</div><p class="help">This is a rule-based assistant, not a prediction service. Advice uses actual yellow-card events. Dismissals and suspensions are not simulated. All unscouted estimates stay broad.</p></div>`;
  const d=showModal('Your assistant’s notebook',body);d.querySelectorAll('[data-review-advice]').forEach(b=>b.onclick=()=>reviewAdvice(recommendations[Number(b.dataset.reviewAdvice)]));
}
function reviewAdvice(rec){try{const changes=recommendationPlan(state,rec);const d=showModal('Review recommendation',`<div class="modal-body"><h3>${esc(rec.title)}</h3><p class="muted small" style="margin-top:8px">${esc(rec.reason)}</p><h3 style="margin:22px 0 12px">Exactly what will change</h3><ul class="change-list">${changes.map(change=>`<li>${esc(change)}</li>`).join('')}</ul><div class="notice warn" style="margin-top:20px">${esc(rec.tradeoff)}</div><p class="help">Your money and player contracts stay unchanged. You choose whether to apply this plan.</p></div>`,`<div class="modal-footer"><button class="btn" id="advice-back">Back to advice</button><button class="btn primary" id="advice-confirm">Apply recommendation</button></div>`);d.querySelector('#advice-back').onclick=askAssistant;d.querySelector('#advice-confirm').onclick=()=>{try{applyRecommendation(state,rec);save();render();d.close();toast('Recommendation applied.');}catch(e){toast(e.message,true);}};}catch(e){toast(e.message,true);}}
function showStyleHelp(){showModal('Six ways to play',`<div class="modal-body"><div class="advice-list">${Object.entries(TACTICAL_STYLES).map(([name,style])=>`<section class="advice-card"><h3>${name}</h3><p>${esc(style.description)}</p><p class="small muted"><strong>Suits:</strong> ${esc(style.suits)}</p><p class="small positive"><strong>Strengths:</strong> ${esc(style.strengths)}</p><p class="tradeoff"><strong>Tradeoff:</strong> ${esc(style.weaknesses)}</p><p class="tiny muted">${Object.entries(style.settings).map(([k,v])=>`${title(k)}: ${v}`).join(' · ')}</p></section>`).join('')}</div><p class="help">No preset overrides attributes, guarantees a result, or changes your formation. Pick one, observe the match, and adjust your instructions.</p></div>`);}
